const ZadBottomNav=(()=>{"use strict";const TABS=[{id:"home",icon:"🏠",label:"الرئيسية",href:"index.html",pages:["index.html","summary.html","profile.html","badges.html","hasad.html","hasad-month.html","ghars.html","about.html","demo.html","report.html","developer.html","diagnostics.html","zad_al_ashr.html","404.html"]},{id:"quran",icon:"📖",label:"القرآن",href:"mushaf.html",pages:["mushaf.html","mushaf-quran.html","tasmee.html"]},{id:"adhkar",icon:"🤲",label:"الأذكار",href:"adhkar.html",pages:["adhkar.html","adhkar-categories.html","adhkar-section.html","hasn.html","du'a.html","duas.html","dua-guide.html","arafah-dua.html","ruqyah.html","asma.html","nawawi.html","sunan.html","takbeer.html"]},{id:"prayer",icon:"🕌",label:"الصلاة",href:"prayers.html",pages:["prayers.html","qibla.html","hijri.html","taqweem.html","barnamaj.html","worship.html"]},{id:"more",icon:"⚙️",label:"المزيد",href:"#more-menu",pages:["manasik.html","odhiya.html","arafah.html","zakat.html","zakat-ahkam.html","zakat-anwa.html","fadael.html","videos.html","playlist.html","Quran-radio.HTML","maktaba-nassiya.html","ai.html","groups.html","group-board.html","groups-privacy.html","hawwa.html","zahra.html","sadaqah.html","kids.html","kids-school.html","kids-creativity.html","kids-heroes.html","kids-fun.html","kids-parents.html","hikayat-hajj.html","settings.html","privacy.html"]}];const MORE_ITEMS=[{icon:"🕋",label:"مناسك الحج",href:"manasik.html"},{icon:"📅",label:"برنامج اليوم",href:"barnamaj.html"},{icon:"💝",label:"صدقة",href:"sadaqah.html"},{icon:"🧮",label:"حاسبة الزكاة",href:"zakat.html"},{icon:"👨‍👩‍👧",label:"التنافس العائلي",href:"groups.html"},{icon:"🌟",label:"ركن الأطفال",href:"kids.html"},{icon:"📺",label:"المحاضرات",href:"videos.html"},{icon:"📻",label:"إذاعة القرآن",href:"Quran-radio.HTML"},{icon:"🎵",label:"البلاي ليست",href:"playlist.html"},{icon:"🤖",label:"تدبّر بالذكاء",href:"ai.html"},{icon:"💎",label:"أسماء الله الحسنى",href:"asma.html"},{icon:"🏅",label:"أوسمتي",href:"badges.html"},{icon:"📊",label:"حصاد العشر",href:"hasad.html"},{icon:"⚙️",label:"الإعدادات",href:"settings.html"}];const KID_TABS=[{id:"khome",icon:"🏠",label:"الركن",href:"kids.html",pages:["kids.html","kids-parents.html","hikayat-hajj.html"]},{id:"kschool",icon:"🎓",label:"مدرستي",href:"kids-school.html",pages:["kids-school.html"]},{id:"kcreate",icon:"🎨",label:"إبداع",href:"kids-creativity.html",pages:["kids-creativity.html"]},{id:"kfun",icon:"🎬",label:"المرح",href:"kids-fun.html",pages:["kids-fun.html","kids-heroes.html"]},{id:"kadult",icon:"👨‍👩‍👧",label:"الكبار",action:"ZadBottomNav.setMode('adult')",pages:[]}];const MODE_KEY="zad_nav_mode";function getMode(){try{return localStorage.getItem(MODE_KEY)==="kids"?"kids":"adult"}catch(e){return"adult"}}function activeTabs(){return getMode()==="kids"?KID_TABS:TABS}function setMode(m){const mode=m==="kids"?"kids":"adult";try{localStorage.setItem(MODE_KEY,mode)}catch(e){}window.location.href=mode==="kids"?"kids.html":"index.html"}let moreOpen=false;function getActiveTab(){const page=window.location.pathname.split("/").pop()||"index.html";const tabs=activeTabs();for(const tab of tabs){if(tab.pages.includes(page))return tab.id;if(tab.href===page)return tab.id}if(getMode()==="adult"&&MORE_ITEMS.some(i=>i.href===page))return"more";return tabs[0].id}function injectCSS(){if(document.getElementById("zad-bnav-css"))return;const style=document.createElement("style");style.id="zad-bnav-css";style.textContent=`\n      /* ── Bottom Nav ── */\n      .zad-bnav {\n        display: none; /* يظهر فقط على الموبايل */\n        position: fixed; bottom: 0; left: 0; right: 0; z-index: 8000;\n        background: var(--card, #fff);\n        border-top: 1px solid var(--border, #e5e5e5);\n        padding-bottom: env(safe-area-inset-bottom, 0px);\n        box-shadow: 0 -4px 24px rgba(0,0,0,.08);\n      }\n      .zad-bnav-inner {\n        display: flex; align-items: stretch; height: 60px;\n      }\n      .zad-bnav-tab {\n        flex: 1; display: flex; flex-direction: column; align-items: center;\n        justify-content: center; gap: 3px; padding: 6px 4px;\n        background: none; border: none; cursor: pointer; font-family: inherit;\n        color: var(--muted, #888); transition: color .2s, background .2s;\n        min-width: 0; text-decoration: none; position: relative;\n        -webkit-tap-highlight-color: transparent; touch-action: manipulation;\n      }\n      .zad-bnav-tab.active { color: var(--green-deep, #0e3b2e); }\n      .zad-bnav-tab.active::before {\n        content: ''; position: absolute; top: 0; left: 25%; right: 25%;\n        height: 3px; background: var(--green-deep, #0e3b2e); border-radius: 0 0 3px 3px;\n      }\n      .zad-bnav-tab:active { background: rgba(0,0,0,.04); }\n      .zad-bnav-icon { font-size: 22px; line-height: 1; }\n      .zad-bnav-label { font-size: 10px; font-weight: 700; white-space: nowrap; overflow: hidden; }\n      \n      /* ── More Sheet ── */\n      .zad-more-overlay {\n        position: fixed; inset: 0; z-index: 7999;\n        background: rgba(0,0,0,.45);\n        opacity: 0; pointer-events: none;\n        transition: opacity .25s;\n      }\n      .zad-more-overlay.open { opacity: 1; pointer-events: auto; }\n      .zad-more-sheet {\n        position: fixed; bottom: 0; left: 0; right: 0; z-index: 8001;\n        background: var(--card, #fff); border-radius: 20px 20px 0 0;\n        padding: 12px 16px calc(env(safe-area-inset-bottom, 0px) + 76px);\n        transform: translateY(100%);\n        transition: transform .3s cubic-bezier(.4,0,.2,1);\n        max-height: 75vh; overflow-y: auto;\n      }\n      .zad-more-sheet.open { transform: translateY(0); }\n      .zad-more-handle {\n        width: 36px; height: 4px; background: var(--border, #ddd);\n        border-radius: 2px; margin: 0 auto 16px;\n      }\n      .zad-more-title {\n        font-size: 14px; font-weight: 800; color: var(--muted, #888);\n        margin-bottom: 12px; text-align: center;\n      }\n      .zad-more-grid {\n        display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px;\n      }\n      .zad-more-item {\n        display: flex; flex-direction: column; align-items: center; gap: 6px;\n        padding: 14px 8px; border-radius: 14px; text-decoration: none;\n        background: var(--sand, #faf9f6); color: var(--ink, #222);\n        font-family: inherit; border: none; cursor: pointer;\n        transition: background .2s; -webkit-tap-highlight-color: transparent;\n        min-height: 72px; justify-content: center;\n      }\n      .zad-more-item:active { background: var(--border, #eee); }\n      .zad-more-item.current { background: var(--green-pale, #e8f4ef); color: var(--green-deep, #0e3b2e); }\n      .zad-more-item.zad-more-mode { background: linear-gradient(135deg, var(--gold,#c9a14a), #e6c97a); color: #3a2e10; font-weight: 900; }\n      .zad-more-item-icon { font-size: 26px; }\n      .zad-more-item-label { font-size: 11px; font-weight: 700; text-align: center; }\n\n      /* ── يظهر على الموبايل فقط ── */\n      @media (max-width: 768px) {\n        .zad-bnav { display: block; }\n        /* تعويض ارتفاع الـ bottom nav */\n        main.main, #main-content, .main {\n          padding-bottom: calc(76px + env(safe-area-inset-bottom, 0px)) !important;\n        }\n        /* القائمة الجانبية تظل متاحة على الموبايل عبر زر القائمة (الدليل الكامل) */\n        main.main, #main-content, .main { margin-right: 0 !important; }\n      }\n\n      @media (prefers-reduced-motion: reduce) {\n        .zad-more-overlay, .zad-more-sheet, .zad-bnav-tab { transition: none !important; }\n      }\n    `;document.head.appendChild(style)}function build(){const activeTab=getActiveTab();const page=window.location.pathname.split("/").pop()||"index.html";const tabs=activeTabs();const nav=document.createElement("nav");nav.className="zad-bnav";nav.setAttribute("aria-label","التنقل الرئيسي");nav.innerHTML=`<div class="zad-bnav-inner">`+tabs.map(tab=>{const isActive=tab.id===activeTab;const isMore=tab.id==="more";const isAction=isMore||!!tab.action;const el=isAction?"button":"a";const onclick=isMore?`ZadBottomNav.toggleMore()`:tab.action||"";const attr=isAction?`onclick="${onclick}"`:`href="${typeof ZadRouter!=="undefined"&&ZadRouter?.getLastPage?.(tab.id)||tab.href}"`;return`\n          <${el}\n            class="zad-bnav-tab${isActive?" active":""}"\n            ${attr}\n            aria-label="${tab.label}"\n            ${isActive?'aria-current="page"':""}>\n            <span class="zad-bnav-icon" aria-hidden="true">${tab.icon}</span>\n            <span class="zad-bnav-label">${tab.label}</span>\n          </${el}>`}).join("")+`</div>`;document.body.appendChild(nav);if(getMode()==="adult"){const overlay=document.createElement("div");overlay.className="zad-more-overlay";overlay.id="zad-more-overlay";overlay.onclick=()=>closeMore();const sheet=document.createElement("div");sheet.className="zad-more-sheet";sheet.id="zad-more-sheet";sheet.innerHTML=`\n        <div class="zad-more-handle"></div>\n        <div class="zad-more-title">المزيد من الميزات</div>\n        <div class="zad-more-grid">\n          <button class="zad-more-item zad-more-mode" onclick="ZadBottomNav.setMode('kids')">\n            <span class="zad-more-item-icon">🌟</span>\n            <span class="zad-more-item-label">وضع الأطفال</span>\n          </button>\n          ${MORE_ITEMS.map(item=>`\n            <a class="zad-more-item${item.href===page?" current":""}"\n               href="${item.href}" onclick="ZadBottomNav.closeMore()">\n              <span class="zad-more-item-icon">${item.icon}</span>\n              <span class="zad-more-item-label">${item.label}</span>\n            </a>\n          `).join("")}\n        </div>`;document.body.appendChild(overlay);document.body.appendChild(sheet)}}function toggleMore(){moreOpen=!moreOpen;document.getElementById("zad-more-overlay")?.classList.toggle("open",moreOpen);document.getElementById("zad-more-sheet")?.classList.toggle("open",moreOpen);document.querySelectorAll(".zad-bnav-tab").forEach(btn=>{if(btn.getAttribute("aria-label")==="المزيد")btn.classList.toggle("active",moreOpen)})}function closeMore(){moreOpen=false;document.getElementById("zad-more-overlay")?.classList.remove("open");document.getElementById("zad-more-sheet")?.classList.remove("open")}function init(){if(document.querySelector(".zad-bnav"))return;injectCSS();build();document.addEventListener("keydown",e=>{if(e.key==="Escape")closeMore()})}return{init:init,toggleMore:toggleMore,closeMore:closeMore,getActiveTab:getActiveTab,setMode:setMode,getMode:getMode}})();window.ZadBottomNav=ZadBottomNav;document.addEventListener("DOMContentLoaded",()=>ZadBottomNav.init());